"""Read public YouTube attribution metadata; never download a video or infer permission."""
from datetime import datetime, timezone
import html
import json
import re
from urllib.parse import parse_qs, unquote, urlparse


def canonical_url(value):
    value=str(value or '').strip()
    parsed=urlparse(value if '://' in value else 'https://'+value)
    host=(parsed.hostname or '').lower()
    if parsed.scheme not in ('http','https') or parsed.username or parsed.password or parsed.port not in (None,80,443):
        raise ValueError('Paste a normal public YouTube video link.')
    if host in ('youtu.be','www.youtu.be'):
        ident=parsed.path.strip('/').split('/')[0]
    elif host in ('youtube.com','www.youtube.com','m.youtube.com','music.youtube.com'):
        if parsed.path=='/watch':
            ident=parse_qs(parsed.query).get('v',[''])[0]
        elif parsed.path.startswith(('/shorts/','/live/','/embed/')):
            ident=parsed.path.split('/')[2]
        else:
            raise ValueError('Use a video link, not a channel or playlist link.')
    else:
        raise ValueError('Only youtube.com and youtu.be video links are supported.')
    if not re.fullmatch(r'[A-Za-z0-9_-]{11}',ident):
        raise ValueError('This is not a valid YouTube video ID.')
    return 'https://www.youtube.com/watch?v='+ident


def text_of(node):
    if isinstance(node,str):
        return node
    if isinstance(node,dict):
        return str(node.get('simpleText') or ''.join(str(r.get('text','')) for r in node.get('runs',[]) if isinstance(r,dict)))
    return ''


def walk(value,depth=0):
    if depth>40:
        return
    yield value
    if isinstance(value,dict):
        for child in value.values():
            yield from walk(child,depth+1)
    elif isinstance(value,list):
        for child in value:
            yield from walk(child,depth+1)


def license_url(value):
    value=html.unescape(str(value or ''))
    if value.startswith('/redirect') or 'youtube.com/redirect?' in value:
        value=parse_qs(urlparse(value).query).get('q',[''])[0]
    value=unquote(value)
    parsed=urlparse(value)
    if value == '/t/creative_commons' or (parsed.scheme in ('http','https') and (parsed.hostname or '').lower() in ('youtube.com','www.youtube.com') and parsed.path.rstrip('/') == '/t/creative_commons'):
        return 'https://www.youtube.com/t/creative_commons'
    if parsed.scheme in ('http','https') and (parsed.hostname or '').lower() in ('creativecommons.org','www.creativecommons.org') and re.fullmatch(r'/licenses/by(?:-[a-z]+)*/\d+\.\d+/?',parsed.path):
        return 'https://creativecommons.org'+parsed.path.rstrip('/')+'/'
    return ''


def initial_json(page,name):
    pattern=rf'(?:\b(?:var\s+)?{name}\s*=|window\[["\x27]{name}["\x27]\]\s*=)\s*'
    for match in re.finditer(pattern,page):
        try:
            return json.JSONDecoder().raw_decode(page[match.end():])[0]
        except ValueError:
            continue
    return {}


def page_details(page):
    result={}
    player=initial_json(page,'ytInitialPlayerResponse')
    details=player.get('videoDetails',{}) if isinstance(player,dict) else {}
    if details:
        result.update(title=details.get('title',''),author=details.get('author',''))
    data=initial_json(page,'ytInitialData')
    for value in walk(data):
        if not isinstance(value,dict):
            continue
        row=value.get('metadataRowRenderer')
        if not isinstance(row,dict) or text_of(row.get('title')).strip().casefold() not in ('license','licence'):
            continue
        contents=row.get('contents') or []
        result['license']=text_of(contents[0]) if contents else ''
        for child in walk(row):
            if isinstance(child,dict):
                url=license_url(child.get('url',''))
                if url:
                    result['license_url']=url
                    break
        # Only the actual License row counts. CC links in a description or song
        # credit are not evidence for the entire source video's license.
        break
    return result


def fetch(value,get=None,extract=None):
    url=canonical_url(value)
    if get is None:
        import requests
        get=requests.get
    details={}
    try:
        response=get(url+'&hl=en',headers={'User-Agent':'Mozilla/5.0','Accept-Language':'en-US,en;q=0.9'},timeout=12)
        response.raise_for_status()
        details=page_details(response.text[:4_000_000])
    except Exception:
        pass
    if not all(details.get(key) for key in ('title','author','license')):
        try:
            if extract is None:
                from yt_dlp import YoutubeDL
                class Quiet:
                    def debug(self,*a,**k):pass
                    def warning(self,*a,**k):pass
                    def error(self,*a,**k):pass
                options={'skip_download':True,'noplaylist':True,'quiet':True,'no_warnings':True,'logger':Quiet(),'socket_timeout':12,'retries':0,'extractor_retries':0,'ignore_no_formats_error':True,'extractor_args':{'youtube':{'skip':['dash','hls']}}}
                with YoutubeDL(options) as ydl:
                    data=ydl.extract_info(url,download=False)
            else:
                data=extract(url)
            if data and data.get('_type') not in ('playlist','multi_video'):
                details.setdefault('title',data.get('title') or '')
                details.setdefault('author',data.get('creator') or data.get('uploader') or data.get('channel') or '')
                if not details.get('title'):
                    details['title']=data.get('title') or ''
                if not details.get('author'):
                    details['author']=data.get('creator') or data.get('uploader') or data.get('channel') or ''
                if not details.get('license'):
                    details['license']=data.get('license') or ''
                if not details.get('license_url'):
                    details['license_url']=license_url(data.get('license_url','')) or license_url(data.get('license',''))
        except Exception:
            pass
    if not details.get('title') or not details.get('author'):
        # oEmbed is a metadata-only public fallback, with NO license assumption.
        try:
            response=get('https://www.youtube.com/oembed',params={'url':url,'format':'json'},timeout=10)
            response.raise_for_status()
            data=response.json()
            details['title']=details.get('title') or data.get('title','')
            details['author']=details.get('author') or data.get('author_name','')
        except Exception:
            pass
    if not details.get('title') or not details.get('author'):
        raise ValueError('YouTube did not return the public title/creator (private, unavailable, or bot-check). Enter the source fields manually; no video was downloaded.')
    report=str(details.get('license') or 'Not returned by YouTube')
    cc=bool(re.search(r'creative\s+commons|\bcc\s*by\b',report,re.I))
    exact=license_url(details.get('license_url',''))
    if not cc:
        exact=''  # An unrelated CC link must never license the source.
    return {'source_url':url,'title':str(details['title'])[:500],'author':str(details['author'])[:300],'license':report[:500],'license_url':exact,'is_cc':cc,'fetched_at':datetime.now(timezone.utc).isoformat()}


def main():
    import argparse
    parser=argparse.ArgumentParser()
    parser.add_argument('url')
    args=parser.parse_args()
    try:
        print(json.dumps({'ok':True,'details':fetch(args.url)}))
    except Exception as exc:
        print(json.dumps({'ok':False,'error':str(exc)[:500]}))


if __name__=='__main__':
    main()
